let copyFeedbackTimer;
function showCopyFeedback(message,success){clearTimeout(copyFeedbackTimer);const feedback=$('copyFeedback');feedback.textContent=message;feedback.className='status '+(success?'ok':'error');feedback.style.whiteSpace='normal';feedback.hidden=false;if(success)copyFeedbackTimer=setTimeout(()=>{feedback.hidden=true},2000)}
