const maintenancePanel=document.createElement('section');maintenancePanel.className='panel';maintenancePanel.innerHTML='<h3>维护与恢复</h3><div class="actions"><button class="btn" id="fullScan">完整校验扫描</button><button class="btn" id="cancelScan">取消扫描</button><button class="btn" id="viewRemoved">已移除曲目</button></div><p id="scanProgress" class="status"></p>';$('page-overview').append(maintenancePanel);
